fn validate_protocol_error_details(value: &Value) -> bool {
    (value.as_object().is_some_and(|object| {
        object
            .get("kind")
            .is_some_and(|field| field == &serde_json::json!("invalidParameter"))
            && object.get("parameter").is_some_and(|field| {
                field
                    .as_str()
                    .is_some_and(|text| text.chars().count() >= 1 && text.chars().count() <= 64)
            })
            && object
                .keys()
                .all(|key| ["kind", "parameter"].contains(&key.as_str()))
    }) || value.as_object().is_some_and(|object| {
        object
            .get("kind")
            .is_some_and(|field| field == &serde_json::json!("constraint"))
            && object.get("reason").is_some_and(|field| {
                field
                    .as_str()
                    .is_some_and(|text| text.chars().count() >= 1 && text.chars().count() <= 200)
            })
            && object
                .keys()
                .all(|key| ["kind", "reason"].contains(&key.as_str()))
    }) || value.as_object().is_some_and(|object| {
        object
            .get("kind")
            .is_some_and(|field| field == &serde_json::json!("jiraFailed"))
            && object
                .get("reason")
                .is_some_and(|field| validate_pm_jira_failure(field))
            && object
                .keys()
                .all(|key| ["kind", "reason"].contains(&key.as_str()))
    }))
}

